import Link from 'next/link'
import { useEffect, useMemo, useState } from 'react'
import QRCode from 'qrcode'
import { Activity, ArrowUpRight, Bike, Bell, Boxes, CalendarDays, CheckCircle2, ChevronRight, ClipboardCheck, FileText, Gauge, LayoutDashboard, Menu, MoreHorizontal, Plus, Printer, QrCode, Search, Settings, ShieldCheck, Sparkles, UserRound, Users, Wrench, X } from 'lucide-react'
import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { Badge } from '@/components/ui/badge'
