type Section = 'Resumen' | 'RODEX IDs' | 'Órdenes de trabajo' | 'Estado de órdenes' | 'Clientes' | 'Inventario' | 'Fidelización' | 'Reportes' | 'Configuración'

type Motorcycle = { id: string; bike: string; plate: string; owner: string; km: string; status: string }
const motorcycles: Motorcycle[] = [
  { id: 'RX-004821', bike: 'Hunk 160 2V', plate: 'ABC123', owner: 'Laura Mendoza', km: '24.850', status: 'En taller' },
  { id: 'RX-004822', bike: 'NKD 125', plate: 'KLM768', owner: 'Daniel Rojas', km: '18.320', status: 'Terminada' },
  { id: 'RX-004823', bike: 'Pulsar NS 200', plate: 'JFT492', owner: 'Santiago Pérez', km: '31.105', status: 'Esperando repuesto' },
  { id: 'RX-004824', bike: 'Gixxer 150', plate: 'MNP207', owner: 'Valentina Gil', km: '12.480', status: 'Activa' },
]
const inventoryProducts = ['Kit de arrastre', 'Aceite 10W40', 'Pastillas de freno', 'Filtros de aceite']
const clients = ['Laura Mendoza', 'Daniel Rojas', 'Santiago Pérez', 'Valentina Gil']
const navGroups = [
  { title: '', items: [{ label: 'Resumen', icon: LayoutDashboard }, { label: 'RODEX IDs', icon: QrCode, count: '128' }, { label: 'Órdenes de trabajo', icon: ClipboardCheck, count: '12' }, { label: 'Estado de órdenes', icon: Activity }, { label: 'Clientes', icon: Users }, { label: 'Inventario', icon: Boxes, count: '3' }] },
  { title: 'Relación y control', items: [{ label: 'Fidelización', icon: Sparkles }, { label: 'Reportes', icon: FileText }, { label: 'Configuración', icon: Settings }] },
]
const history = [{ date: '04 OCT 2026', km: '24.850 KM', title: 'Cambio de aceite + revisión general', meta: 'Carlos Ramírez · OT-000245' }, { date: '18 JUL 2026', km: '22.100 KM', title: 'Cambio de aceite y filtro', meta: 'Andrés López · OT-000198' }, { date: '02 ABR 2026', km: '19.600 KM', title: 'Kit de arrastre', meta: 'Carlos Ramírez · OT-000142' }]

function Logo() { return <div className="flex items-center gap-2.5"><div className="flex size-9 items-center justify-center rounded-xl bg-[#ed1c24] text-lg font-black italic text-white">R</div><div><div className="text-lg font-black tracking-[0.18em] text-white">RODE<span className="text-[#ed1c24]">X</span></div><div className="text-[8px] font-semibold tracking-[0.18em] text-zinc-500">TODO PARA SEGUIR RODANDO</div></div></div> }
function StatusBadge({ status }: { status: string }) { const styles: Record<string, string> = { 'En taller': 'border-red-500/25 bg-red-500/10 text-red-400', Terminada: 'border-emerald-500/25 bg-emerald-500/10 text-emerald-400', 'Esperando repuesto': 'border-amber-500/25 bg-amber-500/10 text-amber-400', Activa: 'border-zinc-700 bg-zinc-800 text-zinc-300' }; return <Badge variant="outline" className={styles[status] ?? ''}>{status}</Badge> }
function QrPreview({ rodexId, compact = false }: { rodexId: string; compact?: boolean }) {
  const [src, setSrc] = useState('')
  const destination = typeof window === 'undefined' ? `/rodexid=${rodexId}` : `${window.location.origin}/rodexid=${rodexId}`
  useEffect(() => { QRCode.toDataURL(destination, { margin: 1, width: compact ? 112 : 220, errorCorrectionLevel: 'H', color: { dark: '#050505', light: '#ffffff' } }).then(setSrc).catch(() => setSrc('')) }, [destination, compact])
  return <Link href={`/rodexid=${rodexId}`} aria-label={`Abrir RODEX ID ${rodexId}`} className={`relative mx-auto block aspect-square overflow-hidden rounded-xl border-4 border-[#ed1c24] bg-white p-2 transition hover:scale-105 ${compact ? 'w-20' : 'w-full max-w-[144px]'}`}><div className="flex size-full items-center justify-center">{src ? <img src={src} alt={`Código QR del RODEX ID ${rodexId}`} className="size-full" /> : <span className="text-xs text-black">Generando QR…</span>}</div></Link>
}
function SectionHeader({ section, subtitle, action, onAction }: { section: Section; subtitle: string; action?: string; onAction?: () => void }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 flex items-center gap-2 text-xs font-medium text-zinc-500"><span>RODEX /</span><span className="text-zinc-700">{section}</span></div><h1 className="text-3xl font-bold tracking-tight">{section === 'Resumen' ? <>Buenos días, Mariana <span className="text-[#ed1c24]">.</span></> : section}</h1><p className="mt-1 text-sm text-zinc-500">{subtitle}</p></div>{action && <Button onClick={onAction} className="h-10 gap-2 bg-[#ed1c24] font-semibold text-white hover:bg-[#c9151c]"><Plus data-icon="inline-start" /> {action}</Button>}</div> }
function EmptyAction({ icon: Icon, title, description, action }: { icon: typeof QrCode; title: string; description: string; action: string }) { return <Card className="border-zinc-800/80 bg-[#101213]"><CardContent className="flex min-h-[280px] flex-col items-center justify-center p-8 text-center"><div className="mb-4 flex size-12 items-center justify-center rounded-2xl bg-[#ed1c24]/10 text-[#ed1c24]"><Icon className="size-6" /></div><h2 className="text-lg font-semibold">{title}</h2><p className="mt-2 max-w-md text-sm text-zinc-500">{description}</p><Button className="mt-6 bg-[#ed1c24] text-white hover:bg-[#c9151c]">{action}</Button></CardContent></Card> }

export default function Page() {
  const [activeSection, setActiveSection] = useState<Section>('Resumen')
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [selected, setSelected] = useState(motorcycles[0])
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [newRodexOpen, setNewRodexOpen] = useState(false)
  const [newClientOpen, setNewClientOpen] = useState(false)
  const [notifications, setNotifications] = useState([{ id: 1, title: 'Mantenimiento próximo', description: 'La Hunk 160 2V requiere servicio en 1.200 km.', unread: true }, { id: 2, title: 'Nuevo RODEX ID', description: 'Se registró la motocicleta de Daniel Rojas.', unread: true }, { id: 3, title: 'Inventario bajo', description: 'El kit de arrastre está por debajo del mínimo.', unread: false }])
  const filtered = useMemo(() => motorcycles.filter((m) => `${m.id} ${m.plate} ${m.bike} ${m.owner}`.toLowerCase().includes(query.toLowerCase())), [query])
  const searchResults = useMemo(() => { const term = query.trim().toLowerCase(); if (!term) return []; return [{ type: 'RODEX ID / moto', items: motorcycles.filter((m) => `${m.id} ${m.plate} ${m.bike} ${m.owner}`.toLowerCase().includes(term)).map((m) => `${m.id} · ${m.plate} · ${m.bike}`) }, { type: 'Clientes', items: clients.filter((client) => client.toLowerCase().includes(term)) }, { type: 'Inventario', items: inventoryProducts.filter((product) => product.toLowerCase().includes(term)) }].filter((group) => group.items.length > 0) }, [query])
  const unread = notifications.filter((item) => item.unread).length
  const go = (section: Section) => { setActiveSection(section); setSidebarOpen(false); setQuery('') }
  const goToSearchResult = (type: string) => { go(type === 'Inventario' ? 'Inventario' : type === 'Clientes' ? 'Clientes' : 'RODEX IDs') }

  return <div className="min-h-screen bg-[#090a0b] text-zinc-100">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[min(84vw,252px)] flex-col border-r border-zinc-800/80 bg-[#0d0f10] transition-transform lg:translate-x-0 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex h-[82px] shrink-0 items-center justify-between border-b border-zinc-800/80 px-5 sm:px-6"><Logo /><Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setSidebarOpen(false)} aria-label="Cerrar navegación"><X /></Button></div><div className="flex min-h-0 flex-1 flex-col gap-7 overflow-y-auto px-3 py-6 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">{navGroups.map((group, index) => <div key={group.title}><div className="px-3 pb-3 text-[10px] font-bold uppercase tracking-[0.2em] text-zinc-600">{index ? group.title : ''}</div><nav className="flex flex-col gap-1">{group.items.map((item) => <button type="button" key={item.label} onClick={() => go(item.label as Section)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm transition ${activeSection === item.label ? 'bg-[#ed1c24]/10 font-semibold text-white' : 'text-zinc-500 hover:bg-zinc-900 hover:text-zinc-200'}`}><item.icon className={`size-[17px] ${activeSection === item.label ? 'text-[#ed1c24]' : ''}`} />{item.label}{item.count && <span className="ml-auto rounded-md bg-zinc-800 px-1.5 py-0.5 text-[10px] text-zinc-400">{item.count}</span>}</button>)}</nav></div>)}</div><div className="shrink-0 border-t border-zinc-800/80 p-4"><div className="flex items-center gap-3"><Avatar className="size-8"><AvatarFallback className="bg-red-500/15 text-xs text-red-400">MR</AvatarFallback></Avatar><div className="flex-1"><div className="text-xs font-semibold">Mariana Ríos</div><div className="text-[10px] text-zinc-600">Administrador</div></div><MoreHorizontal className="size-4 text-zinc-600" /></div></div></aside>{sidebarOpen && <button type="button" aria-label="Cerrar menú" onClick={() => setSidebarOpen(false)} className="fixed inset-0 z-30 bg-black/60 lg:hidden" />}
    <main className="min-w-0 lg:pl-[252px]"><header className="relative sticky top-0 z-20 flex-nowrap border-b border-zinc-800/80 bg-[#090a0b]/95 px-3 py-3 pr-28 backdrop-blur-xl sm:px-8"><div className="flex min-w-0 flex-1 items-center gap-2 sm:gap-3"><Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setSidebarOpen(true)} aria-label="Abrir navegación"><Menu /></Button><div className="relative hidden w-[340px] sm:block"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-zinc-600" /><Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar RODEX ID, placa, cliente..." className="h-10 border-zinc-800 bg-zinc-900/70 pl-10 text-sm placeholder:text-zinc-600" /></div><div className="relative min-w-0 flex-1 sm:hidden"><Search className="absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-zinc-600" /><Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar..." aria-label="Buscar" className="h-9 w-full max-w-[150px] border-zinc-800 bg-zinc-900/70 pl-8 text-xs placeholder:text-zinc-600" /></div></div>{searchResults.length > 0 && <div className="absolute left-3 right-28 top-[58px] z-50 rounded-xl border border-zinc-800 bg-[#111314] p-2 shadow-2xl sm:left-8 sm:right-auto sm:top-[62px] sm:w-[340px]"><p className="px-3 py-2 text-[10px] font-bold uppercase tracking-widest text-zinc-600">Resultados de búsqueda</p>{searchResults.map((group) => <div key={group.type} className="border-t border-zinc-800/70 px-3 py-2"><p className="text-[11px] font-semibold text-[#ed1c24]">{group.type}</p>{group.items.map((item) => <button type="button" key={item} onClick={() => goToSearchResult(group.type)} className="mt-1 block w-full rounded px-1 text-left text-xs text-zinc-300 hover:bg-zinc-800 hover:text-white">{item}</button>)}</div>)}</div>}<div className="absolute right-3 top-3 flex shrink-0 items-center gap-2 sm:right-8"><div className="relative"><Button variant="outline" size="icon" onClick={() => setNotificationsOpen(!notificationsOpen)} aria-label="Notificaciones" className="border-zinc-800 bg-transparent text-zinc-400 hover:text-white"><Bell />{unread > 0 && <span className="absolute right-1.5 top-1.5 size-1.5 rounded-full bg-[#ed1c24]" />}</Button>{notificationsOpen && <div className="fixed left-2 right-2 top-[58px] z-50 w-auto sm:absolute sm:left-auto sm:right-0 sm:top-12 sm:w-[320px] rounded-xl border border-zinc-800 bg-[#111314] p-2 shadow-2xl"><div className="flex items-center justify-between px-3 py-2 text-sm font-semibold">Notificaciones{unread > 0 && <button type="button" className="text-[10px] font-normal text-[#ed1c24]" onClick={() => setNotifications((items) => items.map((item) => ({ ...item, unread: false })))}>Marcar leídas</button>}</div>{notifications.map((item) => <button type="button" key={item.id} onClick={() => setNotifications((items) => items.map((entry) => entry.id === item.id ? { ...entry, unread: false } : entry))} className="flex w-full gap-3 rounded-lg p-3 text-left hover:bg-zinc-900"><span className={`mt-1.5 size-2 shrink-0 rounded-full ${item.unread ? 'bg-[#ed1c24]' : 'bg-zinc-700'}`} /><span><span className="block text-xs font-semibold">{item.title}</span><span className="mt-1 block text-[11px] text-zinc-500">{item.description}</span></span></button>)}</div>}</div><Button variant="ghost" size="icon" aria-label="Perfil de usuario" className="shrink-0 rounded-full border border-zinc-800 bg-zinc-900/70"><span className="text-xs font-bold">MS</span></Button></div></header>
      <div className="mx-auto max-w-[1440px] px-5 py-7 sm:px-8 lg:px-10"><SectionHeader section={activeSection} subtitle={activeSection === 'Resumen' ? 'Aquí tienes el pulso de tu operación hoy.' : `Gestiona ${activeSection.toLowerCase()} desde tu espacio RODEX.`} action={activeSection === 'Resumen' ? 'Registrar motocicleta' : activeSection === 'RODEX IDs' ? 'Nuevo RODEX ID' : activeSection === 'Órdenes de trabajo' ? undefined : activeSection === 'Clientes' ? 'Nuevo cliente' : undefined} onAction={activeSection === 'RODEX IDs' ? () => setNewRodexOpen(true) : activeSection === 'Clientes' ? () => setNewClientOpen(true) : undefined} />{newRodexOpen && <NewRodexModal onClose={() => setNewRodexOpen(false)} />}{newClientOpen && <NewClientModal onClose={() => setNewClientOpen(false)} />}{activeSection === 'Resumen' && <Dashboard filtered={filtered} selected={selected} setSelected={setSelected} />}{activeSection === 'RODEX IDs' && <RodexIds motorcycles={filtered} />}{activeSection === 'Órdenes de trabajo' && <WorkOrders motorcycles={motorcycles} onOpenStatus={() => go('Estado de órdenes')} />}{activeSection === 'Estado de órdenes' && <OrderStatusOverview />}{activeSection === 'Clientes' && <ClientDirectoryV2 />}{activeSection === 'Inventario' && <InventoryPro />}{activeSection === 'Fidelización' && <Loyalty />}{activeSection === 'Reportes' && <Reports />}{activeSection === 'Configuración' && <SettingsView />}</div></main>
  </div>
}

function NewRodexModal({ onClose }: { onClose: () => void }) { const [files, setFiles] = useState<string[]>([]); const fields = [['plate','Placa'],['brand','Marca'],['model','Modelo'],['year','Año'],['engine','Cilindraje'],['color','Color'],['km','Kilometraje'],['owner','Propietario'],['phone','Teléfono'],['email','Correo electrónico']]; return <div role="dialog" aria-modal="true" aria-label="Nuevo RODEX ID" className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/75 p-3 sm:p-6"><Card className="my-4 w-full max-w-4xl border-[#ed1c24]/40 bg-[#101213] sm:my-8"><CardHeader className="flex flex-row items-start justify-between gap-4"><div><CardTitle>Registrar nuevo RODEX ID</CardTitle><p className="mt-1 text-sm text-zinc-500">Completa la ficha digital del automotor.</p></div><Button variant="ghost" size="icon" onClick={onClose} aria-label="Cerrar modal"><X /></Button></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><label className="text-xs text-zinc-400 sm:col-span-2">Cliente previamente creado<select className="mt-2 h-10 w-full rounded-md border border-zinc-800 bg-zinc-900 px-3 text-sm text-zinc-200"><option>Laura Mendoza · cliente@rodex.co</option><option>Daniel Rojas · daniel@rodex.co</option><option>Santiago Pérez · santiago@rodex.co</option></select></label>{fields.map(([name, label]) => <label key={name} className="text-xs text-zinc-400">{label}<Input name={name} className="mt-2 border-zinc-800 bg-zinc-900" /></label>)}<label className="text-xs text-zinc-400">Estado general<select className="mt-2 h-10 w-full rounded-md border border-zinc-800 bg-zinc-900 px-3 text-sm text-zinc-200"><option>Activa</option><option>En taller</option><option>Requiere revisión</option></select></label><label className="text-xs text-zinc-400">Video<input type="file" accept="video/*" className="mt-2 block w-full rounded-md border border-zinc-800 bg-zinc-900 p-2 text-xs text-zinc-400" /></label><label className="text-xs text-zinc-400 sm:col-span-2">Fotografías<input type="file" accept="image/*" multiple onChange={(event) => setFiles(Array.from(event.target.files ?? []).map((file) => URL.createObjectURL(file)))} className="mt-2 block w-full rounded-md border border-zinc-800 bg-zinc-900 p-2 text-xs text-zinc-400" />{files.length > 0 && <span className="mt-2 block text-xs text-emerald-400">{files.length} fotografía(s) seleccionada(s)</span>}</label><label className="text-xs text-zinc-400">Daños existentes<textarea className="mt-2 min-h-24 w-full rounded-md border border-zinc-800 bg-zinc-900 p-3 text-sm text-zinc-200" /></label><label className="text-xs text-zinc-400">Observaciones<textarea className="mt-2 min-h-24 w-full rounded-md border border-zinc-800 bg-zinc-900 p-3 text-sm text-zinc-200" /></label><div className="flex justify-end gap-2 sm:col-span-2"><Button type="button" variant="outline" onClick={onClose} className="border-zinc-700">Cancelar</Button><Button type="button" onClick={onClose} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">Crear RODEX ID</Button></div></CardContent></Card></div> }

function NewClientModal({ onClose }: { onClose: () => void }) { const [saved, setSaved] = useState(false); return <div role="dialog" aria-modal="true" aria-label="Nuevo cliente" className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4"><Card className="w-full max-w-lg border-[#ed1c24]/40 bg-[#101213]"><CardHeader className="flex flex-row items-center justify-between"><div><CardTitle>Nuevo cliente</CardTitle><p className="mt-1 text-sm text-zinc-500">Registra los datos básicos del propietario.</p></div><Button variant="ghost" size="icon" onClick={onClose} aria-label="Cerrar modal"><X /></Button></CardHeader><CardContent className="grid gap-4"><label className="text-xs text-zinc-400">Nombre completo<Input className="mt-2 border-zinc-800 bg-zinc-900" placeholder="Nombre y apellido" /></label><label className="text-xs text-zinc-400">Teléfono<Input className="mt-2 border-zinc-800 bg-zinc-900" placeholder="+57 300 000 0000" /></label><label className="text-xs text-zinc-400">Correo electrónico<Input type="email" className="mt-2 border-zinc-800 bg-zinc-900" placeholder="cliente@correo.com" /></label>{saved && <p className="text-sm text-emerald-400">Cliente listo para asociar a un RODEX ID.</p>}<div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose} className="border-zinc-700">Cancelar</Button><Button onClick={() => setSaved(true)} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">Guardar cliente</Button></div></CardContent></Card></div> }

function Dashboard({ filtered, selected, setSelected }: { filtered: Motorcycle[]; selected: Motorcycle; setSelected: (m: Motorcycle) => void }) { return <div className="flex flex-col gap-6"><Card className="overflow-hidden border-zinc-800/80 bg-gradient-to-br from-[#17191b] via-[#101213] to-[#241012]"><CardContent className="flex flex-col justify-between gap-5 p-5 sm:flex-row sm:items-center sm:p-7"><div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-[#ed1c24]">Centro de operaciones</p><h2 className="mt-2 text-2xl font-bold">Todo listo para seguir rodando</h2><p className="mt-2 max-w-xl text-sm text-zinc-400">Supervisa el taller, prioriza las motos pendientes y mantén cada RODEX ID actualizado.</p></div><div className="grid grid-cols-2 gap-2 text-center"><div className="rounded-xl border border-zinc-800 bg-black/20 px-5 py-3"><p className="text-xl font-bold">{filtered.length}</p><p className="text-[10px] text-zinc-500">Coincidencias</p></div><div className="rounded-xl border border-zinc-800 bg-black/20 px-5 py-3"><p className="text-xl font-bold text-emerald-400">98%</p><p className="text-[10px] text-zinc-500">Operación</p></div></div></CardContent></Card><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[['Motos atendidas hoy','24','+12.5%',Bike],['En taller ahora','08','3 esperando',Wrench],['Ventas del día','$2.840.000','+8.2%',ArrowUpRight],['Próximos mantenimientos','16','esta semana',CalendarDays]].map(([label,value,trend,Icon]) => <Card key={String(label)} className="border-zinc-800/80 bg-[#101213]"><CardContent className="flex items-start justify-between p-5"><div><p className="text-xs text-zinc-500">{label}</p><p className="mt-2 text-2xl font-bold">{value}</p><p className="mt-2 text-[11px] text-emerald-400">{trend}</p></div><Icon className="size-5 text-[#ed1c24]" /></CardContent></Card>)}</div><div className="grid gap-6 xl:grid-cols-[1.35fr_0.65fr]"><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Actividad RODEX ID</CardTitle></CardHeader><CardContent className="p-0">{filtered.map((m) => <button type="button" key={m.id} onClick={() => setSelected(m)} className="flex w-full items-center gap-4 border-t border-zinc-800/70 px-5 py-4 text-left hover:bg-zinc-900/70"><QrCode className="size-5 text-[#ed1c24]" /><div className="min-w-0 flex-1"><div className="font-mono text-xs font-bold text-[#ed1c24]">{m.id} <span className="font-sans font-normal text-zinc-300">— {m.bike}</span></div><p className="mt-1 text-xs text-zinc-500">{m.owner} · {m.plate} · {m.km} km</p></div><StatusBadge status={m.status} /></button>)}</CardContent></Card><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>RODEX ID seleccionado</CardTitle></CardHeader><CardContent><div className="flex items-center gap-4"><div className="flex-1"><h3 className="text-xl font-bold">{selected.bike}</h3><p className="mt-1 text-xs text-zinc-500">{selected.plate} · {selected.owner}</p><Badge className="mt-3 bg-zinc-800 font-mono text-zinc-300">{selected.id}</Badge></div><QrPreview rodexId={selected.id} compact /></div><Separator className="my-5 bg-zinc-800" /><p className="text-xs text-zinc-500">El QR abre la ficha pública de esta motocicleta.</p></CardContent></Card></div></div> }
function RodexIds({ motorcycles: items }: { motorcycles: Motorcycle[] }) {
  const [detailId, setDetailId] = useState<string | null>(null)
  const [editing, setEditing] = useState(false)
  const [procedures, setProcedures] = useState(history.map((event) => event.title))
  const [photos, setPhotos] = useState<string[]>([])
  const moto = items.find((item) => item.id === detailId)
  const [form, setForm] = useState({ plate: '', brand: 'Hero', model: '', year: '2024', engine: '160 cc', color: 'Negro / Rojo', km: '', owner: '', phone: '+57 300 123 4567', email: 'cliente@rodex.co', status: 'Mantenimiento al día', damages: 'Rayón superficial en carenaje lateral derecho.', notes: 'Cliente solicita revisar tensión de cadena y verificar sistema de frenos en cada servicio.' })
  useEffect(() => { if (moto) setForm((current) => ({ ...current, plate: moto.plate, model: moto.bike, km: moto.km, owner: moto.owner })) }, [moto])
  const updateField = (field: keyof typeof form, value: string) => setForm((current) => ({ ...current, [field]: value }))

  if (moto) return <div className="flex flex-col gap-5">
    <button type="button" onClick={() => setDetailId(null)} className="flex w-fit items-center gap-2 text-sm text-zinc-400 hover:text-white"><ChevronRight className="rotate-180 size-4" /> Volver a RODEX IDs</button>
    <div className="grid gap-5 xl:grid-cols-[1.2fr_0.8fr]">
      <Card className="border-zinc-800/80 bg-[#101213]"><CardHeader className="flex flex-col items-start justify-between gap-4 sm:flex-row"><div><p className="font-mono text-sm font-bold text-[#ed1c24]">{moto.id}</p><CardTitle className="mt-2 text-2xl">Ficha digital del automotor</CardTitle><p className="mt-1 text-sm text-zinc-500">Vista interna para el equipo del taller</p></div><div className="flex flex-wrap items-center gap-2"><Button type="button" size="sm" variant="outline" onClick={() => window.print()} className="border-zinc-700"><Printer className="mr-1 size-4" /> Imprimir ficha</Button><Button type="button" size="sm" variant="outline" onClick={() => window.print()} className="border-zinc-700"><QrCode className="mr-1 size-4" /> Imprimir QR</Button>{editing && <Button type="button" size="sm" onClick={() => setEditing(false)} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">Guardar cambios</Button>}{!editing && <Button type="button" size="sm" variant="outline" onClick={() => setEditing(true)} className="border-zinc-700">Editar ficha</Button>}<StatusBadge status={form.status} /></div></CardHeader><CardContent className="flex flex-col gap-6">
        <div className="grid gap-3 sm:grid-cols-2">{([['plate','Placa'],['brand','Marca'],['model','Modelo'],['year','Año'],['engine','Cilindraje'],['color','Color'],['km','Kilometraje'],['status','Estado general']] as const).map(([field, label]) => editing ? <label key={field} className="rounded-xl border border-zinc-800 bg-zinc-900/50 p-3"><span className="text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-600">{label}</span><Input value={form[field]} onChange={(event) => updateField(field, event.target.value)} className="mt-1 h-8 border-zinc-700 bg-zinc-950 text-sm" /></label> : <DetailField key={field} label={label} value={field === 'km' ? `${form[field]} km` : form[field]} />)}</div>
        <Separator /><div><h3 className="mb-3 text-sm font-semibold">Propietario</h3><div className="grid gap-3 sm:grid-cols-3">{([['owner','Nombre completo'],['phone','Teléfono'],['email','Correo electrónico']] as const).map(([field, label]) => editing ? <label key={field} className="rounded-xl border border-zinc-800 bg-zinc-900/50 p-3"><span className="text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-600">{label}</span><Input value={form[field]} onChange={(event) => updateField(field, event.target.value)} className="mt-1 h-8 border-zinc-700 bg-zinc-950 text-sm" /></label> : <DetailField key={field} label={label} value={form[field]} />)}</div></div>
        <div className="grid gap-4 sm:grid-cols-2"><label><span className="mb-2 block text-sm font-semibold">Daños existentes</span>{editing ? <textarea value={form.damages} onChange={(event) => updateField('damages', event.target.value)} className="min-h-24 w-full rounded-xl border border-zinc-800 bg-zinc-900/60 p-3 text-sm text-zinc-200 outline-none focus:border-[#ed1c24]" /> : <div className="rounded-xl border border-amber-500/20 bg-amber-500/5 p-4 text-sm text-amber-200">{form.damages}</div>}</label><label><span className="mb-2 block text-sm font-semibold">Observaciones</span>{editing ? <textarea value={form.notes} onChange={(event) => updateField('notes', event.target.value)} className="min-h-24 w-full rounded-xl border border-zinc-800 bg-zinc-900/60 p-3 text-sm text-zinc-200 outline-none focus:border-[#ed1c24]" /> : <div className="rounded-xl border border-zinc-800 bg-zinc-900/60 p-4 text-sm leading-6 text-zinc-400">{form.notes}</div>}</label></div>
      </CardContent></Card>
      <div className="flex flex-col gap-5"><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>RODEX ID y acceso público</CardTitle></CardHeader><CardContent className="flex flex-col items-center gap-4"><div className="print-qr-card rounded-[2rem] border-4 border-[#ed1c24] bg-black p-5 text-center"><p className="text-2xl font-black tracking-[0.2em] text-white">RODEX</p><p className="mb-3 text-[9px] uppercase tracking-[0.22em] text-zinc-400">La identidad digital de tu moto</p><QrPreview rodexId={moto.id} /><p className="mt-3 text-xs font-semibold text-white">ESCANEA EL QR</p><p className="text-[10px] text-zinc-400">Descubre la historia de esta moto</p></div><p className="text-center text-xs text-zinc-500">El QR abre la vista del cliente en <span className="font-mono text-zinc-300">/rodexid={moto.id}</span></p><Link href={`/rodexid=${moto.id}`} className="inline-flex items-center gap-2 text-sm text-[#ed1c24] hover:underline">Abrir vista cliente <ArrowUpRight className="size-4" /></Link></CardContent></Card><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Fotografías y video</CardTitle></CardHeader><CardContent className="grid grid-cols-2 gap-3"><label className="col-span-2 flex cursor-pointer items-center justify-center rounded-xl border border-dashed border-zinc-700 p-3 text-xs text-zinc-400 hover:border-[#ed1c24] hover:text-white"><Plus className="mr-2 size-4" /> Añadir fotos<input type="file" accept="image/*" multiple className="hidden" onChange={(event) => setPhotos(Array.from(event.target.files ?? []).map((file) => URL.createObjectURL(file)))} /></label>{photos.map((photo) => <img key={photo} src={photo} alt="Evidencia añadida" className="aspect-video rounded-xl object-cover" />)}<div className="flex aspect-video items-center justify-center rounded-xl border border-zinc-800 bg-gradient-to-br from-zinc-700 via-zinc-900 to-black text-xs text-zinc-400">Foto frontal</div><div className="flex aspect-video items-center justify-center rounded-xl border border-zinc-800 bg-gradient-to-br from-red-950 via-zinc-900 to-black text-xs text-zinc-400">Foto lateral</div><div className="col-span-2 flex aspect-video items-center justify-center rounded-xl border border-zinc-800 bg-zinc-900 text-xs text-zinc-400">Video de recepción · 00:42</div></CardContent></Card></div>
    </div>
    <Card className="border-zinc-800/80 bg-[#101213]"><CardHeader className="flex flex-row items-center justify-between"><CardTitle>Revisiones y mantenimientos</CardTitle><Button type="button" size="sm" variant="outline" onClick={() => setProcedures((items) => [...items, 'Nuevo procedimiento'])} className="border-zinc-700"><Plus className="mr-1 size-4" /> Añadir</Button></CardHeader><CardContent className="flex flex-col gap-3">{procedures.map((procedure, index) => <div key={`${procedure}-${index}`} className="flex items-center gap-3 rounded-xl border border-zinc-800 p-4"><Wrench className="size-4 text-[#ed1c24]" /><Input value={procedure} onChange={(event) => setProcedures((items) => items.map((item, itemIndex) => itemIndex === index ? event.target.value : item))} className="border-zinc-700 bg-zinc-900" /><Badge variant="outline" className="border-emerald-500/30 text-emerald-400">Registrada</Badge></div>)}{history.map((event) => <div key={event.date} className="flex flex-col gap-2 rounded-xl border border-zinc-800 p-4 sm:flex-row sm:items-center"><div className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-[#ed1c24]/10 text-[#ed1c24]"><Wrench className="size-4" /></div><div className="min-w-0 flex-1"><p className="font-semibold">{event.title}</p><p className="mt-1 text-xs text-zinc-500">{event.date} · {event.km} · {event.meta}</p></div><Badge variant="outline" className="w-fit border-emerald-500/30 text-emerald-400">Completada</Badge></div>)}</CardContent></Card>
  </div>

  return <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{items.map((m) => <Card key={m.id} className="border-zinc-800/80 bg-[#101213]"><CardContent className="flex items-center gap-4 p-5"><QrPreview rodexId={m.id} compact /><div className="min-w-0 flex-1"><p className="font-mono text-sm font-bold text-[#ed1c24]">{m.id}</p><h3 className="mt-1 truncate font-semibold">{m.bike}</h3><p className="mt-1 text-xs text-zinc-500">{m.plate} · {m.owner}</p><button type="button" onClick={() => setDetailId(m.id)} className="mt-3 inline-flex items-center gap-1 text-xs text-zinc-300 hover:text-white">Ver ficha interna <ArrowUpRight className="size-3" /></button></div></CardContent></Card>)}</div>
}

function DetailField({ label, value }: { label: string; value: string }) { return <div className="rounded-xl border border-zinc-800 bg-zinc-900/50 p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-600">{label}</p><p className="mt-1 text-sm font-medium text-zinc-200">{value}</p></div> }
function WorkOrders({ motorcycles, onOpenStatus }: { motorcycles: Motorcycle[]; onOpenStatus: () => void }) { const [showForm, setShowForm] = useState(false); const [initialMedia, setInitialMedia] = useState<string[]>([]); const [selectedOrder, setSelectedOrder] = useState<string | null>(null); const [orderMedia, setOrderMedia] = useState<string[]>([]); const [orders, setOrders] = useState([{ id: 'OT-000245', title: 'Cambio de aceite + revisión', moto: motorcycles[0], status: 'En diagnóstico', detail: 'Cambio de aceite, lubricación de cadena e inspección general.', supplies: 'Aceite 10W40 x1, lubricante de cadena x1' }]); const inventoryOptions = ['Aceite 10W40 · 48 disponibles', 'Kit de arrastre · 12 disponibles', 'Pastillas de freno · 3 disponibles', 'Filtros de aceite · 72 disponibles']; const [showMoreSupplies, setShowMoreSupplies] = useState(false); const [form, setForm] = useState({ motorcycle: motorcycles[0].id, title: '', detail: '', supplies: '' }); const selectedMoto = motorcycles.find((moto) => moto.id === form.motorcycle) ?? motorcycles[0]; const createOrder = () => { if (!form.title || !form.detail || !form.supplies) return; setOrders((current) => [{ id: `OT-${String(current.length + 246).padStart(6, '0')}`, title: form.title, moto: selectedMoto, status: 'Pendiente', detail: form.detail, supplies: form.supplies }, ...current]); setForm({ motorcycle: motorcycles[0].id, title: '', detail: '', supplies: '' }); setShowForm(false) }; return <div className="flex flex-col gap-5">{showForm && <div role="dialog" aria-modal="true" aria-label="Nueva orden de trabajo" className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4"><Card className="max-h-[92vh] w-full max-w-3xl overflow-y-auto border-[#ed1c24]/40 bg-[#101213]"><CardHeader><CardTitle>Nueva orden ligada a una motocicleta</CardTitle><p className="text-sm text-zinc-500">Selecciona el RODEX ID y documenta con detalle el trabajo e insumos.</p></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><label className="text-xs text-zinc-400">Moto y RODEX ID<select value={form.motorcycle} onChange={(event) => setForm({ ...form, motorcycle: event.target.value })} className="mt-2 h-10 w-full rounded-md border border-zinc-800 bg-zinc-900 px-3 text-sm text-zinc-200">{motorcycles.map((moto) => <option key={moto.id} value={moto.id}>{moto.id} · {moto.plate} · {moto.bike}</option>)}</select></label><div className="rounded-lg border border-zinc-800 bg-zinc-900/50 p-3 text-xs text-zinc-400">Propietario: <span className="text-zinc-200">{selectedMoto.owner}</span><br />Kilometraje: <span className="text-zinc-200">{selectedMoto.km} km</span></div><label className="text-xs text-zinc-400">Qué se va a hacer<Input value={form.title} onChange={(event) => setForm({ ...form, title: event.target.value })} placeholder="Ej. Mantenimiento preventivo" className="mt-2 border-zinc-800 bg-zinc-900" /></label><label className="text-xs text-zinc-400">Insumos del inventario<div className="mt-2 grid gap-2">{inventoryOptions.slice(0, showMoreSupplies ? inventoryOptions.length : 1).map((item) => { const selected = form.supplies.split('|').includes(item); return <label key={item} className={`flex cursor-pointer items-center gap-3 rounded-lg border p-3 text-sm transition ${selected ? 'border-[#ed1c24]/60 bg-[#ed1c24]/10 text-white' : 'border-zinc-800 bg-zinc-900/70 text-zinc-400'}`}><input type="checkbox" checked={selected} onChange={() => setForm({ ...form, supplies: selected ? form.supplies.split('|').filter((value) => value !== item).join('|') : [form.supplies, item].filter(Boolean).join('|') })} className="size-4 accent-[#ed1c24]" /><span className="flex-1">{item.split(' · ')[0]}</span><span className="text-[11px] text-zinc-500">{item.split(' · ')[1]}</span></label>})}</div><Button type="button" variant="ghost" size="sm" onClick={() => setShowMoreSupplies((value) => !value)} className="mt-2 px-0 text-[#ed1c24]">{showMoreSupplies ? 'Mostrar menos' : 'Agregar más insumos'}</Button><p className="mt-2 text-[11px] text-zinc-600">La lista refleja las existencias actuales del inventario.</p></label><label className="text-xs text-zinc-400">Fotos iniciales (opcional)<input type="file" accept="image/*" multiple onChange={(event) => setInitialMedia(Array.from(event.target.files ?? []).map((file) => URL.createObjectURL(file)))} className="mt-2 block w-full rounded-md border border-zinc-800 bg-zinc-900 p-2 text-xs text-zinc-400" /></label><label className="text-xs text-zinc-400">Video estado general (opcional)<input type="file" accept="video/*" className="mt-2 block w-full rounded-md border border-zinc-800 bg-zinc-900 p-2 text-xs text-zinc-400" /></label><label className="text-xs text-zinc-400 sm:col-span-2">Detalle del procedimiento<textarea value={form.detail} onChange={(event) => setForm({ ...form, detail: event.target.value })} placeholder="Describe diagnóstico, pasos, hallazgos y criterios de entrega..." className="mt-2 min-h-28 w-full rounded-md border border-zinc-800 bg-zinc-900 p-3 text-sm text-zinc-200" /></label><div className="flex gap-2 sm:col-span-2"><Button type="button" onClick={createOrder} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">Crear orden</Button><Button type="button" variant="outline" onClick={() => setShowForm(false)} className="border-zinc-700">Cancelar</Button></div></CardContent></Card></div>}<div className="flex justify-end"><Button type="button" onClick={() => setShowForm(true)} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]"><Plus className="mr-2 size-4" /> Nueva orden</Button></div>{selectedOrder && <Card className="border-blue-500/30 bg-[#101213]"><CardHeader className="flex flex-row items-center justify-between"><CardTitle>Seguimiento de {selectedOrder}</CardTitle><Button type="button" variant="ghost" size="icon" onClick={() => setSelectedOrder(null)} aria-label="Cerrar seguimiento"><X /></Button></CardHeader><CardContent className="flex flex-col gap-4"><div className="grid gap-3 sm:grid-cols-3"><Badge variant="outline" className="w-fit border-blue-500/40 text-blue-400">En proceso</Badge><span className="text-xs text-zinc-500">Última actualización: hoy, 10:42</span><span className="text-xs text-zinc-500">Técnico: Carlos Ramírez</span></div><div className="rounded-lg border border-zinc-800 bg-zinc-900/50 p-4 text-sm text-zinc-300">Diagnóstico confirmado. Se inició el cambio de aceite y la inspección de frenos.</div><label className="flex cursor-pointer items-center justify-center rounded-lg border border-dashed border-zinc-700 p-4 text-sm text-zinc-400 hover:border-[#ed1c24]">Subir fotos o videos<input type="file" accept="image/*,video/*" multiple className="hidden" onChange={(event) => setOrderMedia(Array.from(event.target.files ?? []).map((file) => URL.createObjectURL(file)))} /></label>{orderMedia.length > 0 && <div className="grid grid-cols-3 gap-2">{orderMedia.map((media) => <img key={media} src={media} alt="Evidencia de orden" className="aspect-video rounded object-cover" />)}</div>}</CardContent></Card>}{orders.map((order) => <Card key={order.id} className="border-zinc-800/80 bg-[#101213]"><CardContent className="flex flex-col gap-4 p-5"><div className="flex flex-wrap items-start gap-4"><div className="flex size-10 items-center justify-center rounded-xl bg-zinc-900 text-[#ed1c24]"><ClipboardCheck className="size-5" /></div><div className="min-w-0 flex-1"><p className="font-mono text-xs text-[#ed1c24]">{order.id}</p><h3 className="mt-1 font-semibold">{order.title}</h3><p className="mt-1 text-xs text-zinc-500">{order.moto.id} · {order.moto.plate} · {order.moto.bike} · {order.moto.owner}</p></div><Badge variant="outline" className="w-fit border-zinc-700 text-zinc-300">{order.status}</Badge><Button type="button" variant="outline" size="sm" onClick={onOpenStatus} className="border-zinc-700">Ver estado</Button></div><div className="grid gap-3 rounded-lg border border-zinc-800 bg-zinc-900/40 p-4 text-xs text-zinc-400 sm:grid-cols-2"><p><strong className="text-zinc-200">Procedimiento:</strong> {order.detail}</p><p><strong className="text-zinc-200">Insumos:</strong> {order.supplies}</p></div></CardContent></Card>)}</div> }
function OrderStatusOverview() { const [detailId, setDetailId] = useState<string | null>(null); const orders = [{ id: 'OT-000245', title: 'Cambio de aceite + revisión general', moto: 'Hunk 160 2V · ABC123', client: 'Laura Mendoza', status: 'En taller', updated: 'Hoy, 10:42' }, { id: 'OT-000244', title: 'Kit de arrastre', moto: 'Pulsar NS 200 · XYZ789', client: 'Daniel Rojas', status: 'Esperando aprobación', updated: 'Ayer, 16:20' }, { id: 'OT-000243', title: 'Revisión general', moto: 'NKD 125 · JKL456', client: 'Santiago Pérez', status: 'Completada', updated: '02 OCT 2026' }]; const selected = orders.find((order) => order.id === detailId); if (selected) return <div className="flex flex-col gap-5"><Button type="button" variant="ghost" onClick={() => setDetailId(null)} className="w-fit text-zinc-400">← Volver a estados</Button><OrderStatus /></div>; return <div className="flex flex-col gap-5"><div className="grid gap-3 sm:grid-cols-3">{[['3','Órdenes activas'],['1','Esperando aprobación'],['1','Completada']].map(([value,label]) => <Card key={label} className="border-zinc-800/80 bg-[#101213]"><CardContent className="p-4"><p className="text-2xl font-bold">{value}</p><p className="mt-1 text-xs text-zinc-500">{label}</p></CardContent></Card>)}</div><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Seguimiento de órdenes</CardTitle><p className="text-sm text-zinc-500">Consulta el estado actual sin abrir toda la información operativa.</p></CardHeader><CardContent className="flex flex-col gap-3">{orders.map((order) => <div key={order.id} className="flex flex-col gap-3 rounded-xl border border-zinc-800 bg-zinc-900/40 p-4 sm:flex-row sm:items-center"><div className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-[#ed1c24]/10 text-[#ed1c24]"><ClipboardCheck className="size-4" /></div><div className="min-w-0 flex-1"><p className="font-mono text-xs text-[#ed1c24]">{order.id}</p><p className="mt-1 font-semibold">{order.title}</p><p className="mt-1 text-xs text-zinc-500">{order.moto} · {order.client}</p></div><div className="flex items-center gap-3"><div className="text-right"><StatusBadge status={order.status} /><p className="mt-1 text-[10px] text-zinc-600">{order.updated}</p></div><Button type="button" size="sm" variant="outline" onClick={() => setDetailId(order.id)} className="border-zinc-700">Ver detalles</Button></div></div>)}</CardContent></Card></div> }

function OrderStatus() { const [notes, setNotes] = useState('Diagnóstico confirmado y trabajo en progreso.'); const [media, setMedia] = useState<string[]>([]); return <div className="grid gap-5 xl:grid-cols-[1.25fr_0.75fr]"><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-mono text-xs text-[#ed1c24]">OT-000245 · RX-004821</p><CardTitle className="mt-2">Cambio de aceite + revisión general</CardTitle><p className="mt-1 text-sm text-zinc-500">Hunk 160 2V · ABC123 · Laura Mendoza</p></div><select defaultValue="En taller" aria-label="Estado de la orden" className="h-9 rounded-lg border border-zinc-700 bg-zinc-900 px-3 text-xs font-semibold text-zinc-200"><option>En taller</option><option>En revisión</option><option>En espera</option><option>Esperando repuesto</option><option>Terminada</option><option>Cancelada</option></select></div></CardHeader><CardContent className="flex flex-col gap-5"><div className="grid gap-3 sm:grid-cols-4">{[['Recibida','04 OCT'],['Diagnóstico','04 OCT'],['En proceso','Hoy'],['Entrega','Pendiente']].map(([label,date], index) => <div key={label} className={`rounded-xl border p-3 ${index === 2 ? 'border-[#ed1c24]/50 bg-[#ed1c24]/10' : 'border-zinc-800 bg-zinc-900/50'}`}><p className="text-xs font-semibold">{label}</p><p className="mt-1 text-[11px] text-zinc-500">{date}</p></div>)}</div><label className="text-xs text-zinc-400">Novedades y notas<textarea value={notes} onChange={(event) => setNotes(event.target.value)} className="mt-2 min-h-32 w-full rounded-xl border border-zinc-800 bg-zinc-900 p-3 text-sm text-zinc-200 outline-none focus:border-[#ed1c24]" /></label><div className="rounded-xl border border-zinc-800 p-4"><p className="text-sm font-semibold">Insumos usados</p><div className="mt-3 flex flex-wrap gap-2"><Badge variant="outline" className="border-zinc-700">Aceite 10W40 × 1</Badge><Badge variant="outline" className="border-zinc-700">Lubricante cadena × 1</Badge><Button type="button" size="sm" variant="outline" className="border-zinc-700">Añadir insumo</Button></div></div><Button type="button" className="w-fit bg-[#ed1c24] text-white hover:bg-[#c9151c]">Guardar modificaciones</Button></CardContent></Card><Card className="h-fit border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Fotos y videos del avance</CardTitle><p className="text-sm text-zinc-500">Evidencia del trabajo realizado.</p></CardHeader><CardContent className="flex flex-col gap-4"><label className="flex cursor-pointer items-center justify-center rounded-xl border border-dashed border-zinc-700 p-5 text-center text-sm text-zinc-400 hover:border-[#ed1c24]">Subir fotos o videos<input type="file" accept="image/*,video/*" multiple className="hidden" onChange={(event) => setMedia(Array.from(event.target.files ?? []).map((file) => URL.createObjectURL(file)))} /></label>{media.length > 0 && <div className="grid grid-cols-2 gap-2">{media.map((src) => <img key={src} src={src} alt="Evidencia de avance" className="aspect-video rounded-lg object-cover" />)}</div>}<div className="rounded-xl border border-zinc-800 bg-zinc-900/50 p-3 text-xs text-zinc-500">Última actualización: hoy, 10:42<br />Técnico asignado: Carlos Ramírez</div></CardContent></Card></div> }

function Clients() { const [selectedClient, setSelectedClient] = useState<string | null>(null); const [editing, setEditing] = useState(false); const data = [{ name: 'Laura Mendoza', phone: '+57 300 123 4567', email: 'laura@correo.com', motos: ['Hunk 160 2V · ABC123', 'Gixxer 150 · MNP207'] }, { name: 'Daniel Rojas', phone: '+57 301 555 2200', email: 'daniel@correo.com', motos: ['NKD 125 · KLM768'] }, { name: 'Santiago Pérez', phone: '+57 302 888 1090', email: 'santiago@correo.com', motos: ['Pulsar NS 200 · JFT492'] }, { name: 'Valentina Gil', phone: '+57 304 222 8811', email: 'valentina@correo.com', motos: ['Gixxer 150 · MNP207'] }]; const client = data.find((item) => item.name === selectedClient); if (client) return <Card className="border-zinc-800/80 bg-[#101213]"><CardHeader className="flex flex-row items-center justify-between"><div><Button variant="ghost" onClick={() => setSelectedClient(null)} className="-ml-3 mb-2 text-xs text-zinc-500">← Clientes</Button><CardTitle>{client.name}</CardTitle></div><Button variant="outline" onClick={() => setEditing(!editing)} className="border-zinc-700">{editing ? 'Guardar' : 'Editar cliente'}</Button></CardHeader><CardContent className="grid gap-5 sm:grid-cols-2"><label className="text-xs text-zinc-400">Teléfono<Input defaultValue={client.phone} disabled={!editing} className="mt-2 border-zinc-800 bg-zinc-900" /></label><label className="text-xs text-zinc-400">Correo electrónico<Input defaultValue={client.email} disabled={!editing} className="mt-2 border-zinc-800 bg-zinc-900" /></label><div className="sm:col-span-2"><p className="text-sm font-semibold">Motocicletas asociadas ({client.motos.length})</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{client.motos.map((moto) => <div key={moto} className="flex items-center justify-between rounded-lg border border-zinc-800 p-3 text-sm"><span>{moto}</span><Button variant="ghost" size="sm" className="text-red-400">Quitar</Button></div>)}</div><Button variant="outline" className="mt-3 border-zinc-700">+ Asociar motocicleta</Button></div><Button variant="outline" className="w-fit border-red-500/30 text-red-400">Eliminar cliente</Button></CardContent></Card>; return <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{[['Laura Mendoza','4 motocicletas','Última visita: hoy','LM'],['Daniel Rojas','2 motocicletas','Última visita: 28 SEP','DR'],['Santiago Pérez','1 motocicleta','Última visita: 21 SEP','SP'],['Valentina Gil','3 motocicletas','Última visita: 18 SEP','VG']].map(([name,motos,last,initials]) => <Card key={name} className="border-zinc-800/80 bg-[#101213]"><CardContent className="flex items-center gap-4 p-5"><Avatar className="size-11"><AvatarFallback className="bg-[#ed1c24]/15 text-[#ed1c24]">{initials}</AvatarFallback></Avatar><div className="min-w-0 flex-1"><h3 className="font-semibold">{name}</h3><p className="mt-1 text-xs text-zinc-400">{motos}</p><p className="mt-1 text-[11px] text-zinc-600">{last}</p></div><ChevronRight className="size-4 text-zinc-600" /></CardContent></Card>)}</div> }
function ClientDirectory() { const [selected, setSelected] = useState<string | null>(null); const [editing, setEditing] = useState(false); const [clientsData, setClientsData] = useState([{ name: 'Laura Mendoza', phone: '+57 300 123 4567', email: 'laura@correo.com', motorcycles: ['Hunk 160 2V · ABC123', 'Gixxer 150 · MNP207'] }, { name: 'Daniel Rojas', phone: '+57 301 555 2200', email: 'daniel@correo.com', motorcycles: ['NKD 125 · KLM768'] }, { name: 'Santiago Pérez', phone: '+57 302 888 1090', email: 'santiago@correo.com', motorcycles: ['Pulsar NS 200 · JFT492'] }, { name: 'Valentina Gil', phone: '+57 304 222 8811', email: 'valentina@correo.com', motorcycles: ['Gixxer 150 · MNP207'] }]); const client = clientsData.find((item) => item.name === selected); if (client) return <div className="flex flex-col gap-5"><Button type="button" variant="ghost" onClick={() => setSelected(null)} className="w-fit text-zinc-400">← Volver a clientes</Button><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-xs uppercase tracking-widest text-zinc-500">Perfil del cliente</p><CardTitle className="mt-1">{client.name}</CardTitle></div><Button type="button" onClick={() => setEditing(!editing)} variant="outline" className="w-fit border-zinc-700">{editing ? 'Guardar cambios' : 'Editar cliente'}</Button></CardHeader><CardContent className="grid gap-5 sm:grid-cols-2"><label className="text-xs text-zinc-400">Teléfono<Input defaultValue={client.phone} disabled={!editing} className="mt-2 border-zinc-800 bg-zinc-900" /></label><label className="text-xs text-zinc-400">Correo electrónico<Input defaultValue={client.email} disabled={!editing} className="mt-2 border-zinc-800 bg-zinc-900" /></label><div className="sm:col-span-2"><div className="flex items-center justify-between"><p className="font-semibold">Motocicletas asociadas ({client.motorcycles.length})</p><Button type="button" size="sm" variant="outline" className="border-zinc-700">Añadir moto</Button></div><div className="mt-3 grid gap-3 sm:grid-cols-2">{client.motorcycles.map((motorcycle) => <div key={motorcycle} className="flex items-center justify-between rounded-xl border border-zinc-800 bg-zinc-900/50 p-4"><span className="text-sm">{motorcycle}</span>{editing && <Button type="button" size="sm" variant="ghost" className="text-red-400">Quitar</Button>}</div>)}</div></div><Button type="button" variant="outline" className="w-fit border-red-500/30 text-red-400">Eliminar cliente</Button></CardContent></Card></div>; return <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{clientsData.map((clientItem) => <Card key={clientItem.name} className="border-zinc-800/80 bg-[#101213]"><CardContent className="flex flex-col gap-4 p-5"><div className="flex items-start gap-3"><Avatar className="size-11"><AvatarFallback className="bg-[#ed1c24]/15 text-[#ed1c24]">{clientItem.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</AvatarFallback></Avatar><div className="min-w-0 flex-1"><h3 className="font-semibold">{clientItem.name}</h3><p className="mt-1 text-xs text-zinc-500">{clientItem.email}</p><p className="mt-1 text-xs text-zinc-500">{clientItem.phone}</p></div></div><div className="flex items-center justify-between border-t border-zinc-800 pt-3"><span className="text-xs text-zinc-500">{clientItem.motorcycles.length} motocicletas asociadas</span><Button type="button" size="sm" onClick={() => { setSelected(clientItem.name); setEditing(false) }} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">Ver cliente</Button></div></CardContent></Card>)}</div> }

function ClientDirectoryV2() { const [query, setQuery] = useState(''); const [filter, setFilter] = useState('Todos'); const [selected, setSelected] = useState<string | null>(null); const [addMoto, setAddMoto] = useState(false); const [newMoto, setNewMoto] = useState(false); const [step, setStep] = useState(1); const [created, setCreated] = useState(false); const [clientsData, setClientsData] = useState([{ name: 'Laura Mendoza', phone: '+57 300 123 4567', email: 'laura@correo.com', status: 'Activo', registered: '12 SEP 2025', motorcycles: [{ brand: 'Hero', model: 'Hunk 160 2V', year: '2024', plate: 'ABC123', km: '24.850', rodex: 'RX-004821', color: 'Negro / Rojo', state: 'Activa' }, { brand: 'Suzuki', model: 'Gixxer 150', year: '2023', plate: 'MNP207', km: '18.230', rodex: 'RX-004822', color: 'Azul', state: 'En servicio' }] }, { name: 'Daniel Rojas', phone: '+57 301 555 2200', email: 'daniel@correo.com', status: 'Activo', registered: '04 OCT 2026', motorcycles: [{ brand: 'AKT', model: 'NKD 125', year: '2022', plate: 'KLM768', km: '32.100', rodex: 'RX-004823', color: 'Negro', state: 'Activa' }] }, { name: 'Santiago Pérez', phone: '+57 302 888 1090', email: 'santiago@correo.com', status: 'Activo', registered: '02 OCT 2026', motorcycles: [{ brand: 'Bajaj', model: 'Pulsar NS 200', year: '2023', plate: 'JFT492', km: '12.400', rodex: 'RX-004824', color: 'Rojo', state: 'Activa' }] }]); const matches = clientsData.filter((client) => `${client.name} ${client.phone} ${client.email} ${client.motorcycles.map((moto) => `${moto.plate} ${moto.rodex}`).join(' ')}`.toLowerCase().includes(query.toLowerCase()) && (filter === 'Todos' || filter === client.status || (filter === 'Con motos' && client.motorcycles.length > 0) || (filter === 'Sin motos' && client.motorcycles.length === 0))); const client = clientsData.find((item) => item.name === selected); const updateClient = (field: 'phone' | 'email', value: string) => { if (!client) return; setClientsData((items) => items.map((item) => item.name === client.name ? { ...item, [field]: value } : item)); }; if (client) return <div className="flex flex-col gap-5">{created && <div role="status" className="rounded-xl border border-emerald-500/30 bg-emerald-500/5 p-4 text-sm text-emerald-300"><p className="font-semibold">RODEX ID creado correctamente</p><p className="mt-1">La motocicleta fue asociada a {client.name}.</p></div>}<Button type="button" variant="ghost" onClick={() => setSelected(null)} className="w-fit text-zinc-400">← Volver a clientes</Button><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><Avatar className="size-14"><AvatarFallback className="bg-[#ed1c24]/15 text-[#ed1c24]">{client.name.split(' ').map((part) => part[0]).join('').slice(0,2)}</AvatarFallback></Avatar><div><p className="text-xs uppercase tracking-widest text-zinc-500">Perfil del cliente · {client.status}</p><h2 className="mt-1 text-2xl font-bold">{client.name}</h2><p className="text-xs text-zinc-500">Registrado el {client.registered}</p></div></div><Button type="button" variant="outline" className="w-fit border-zinc-700">Editar cliente</Button></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><Card className="border-zinc-800 bg-[#101213]"><CardContent className="p-4"><p className="text-xs text-zinc-500">Motocicletas</p><p className="mt-1 text-2xl font-bold">{client.motorcycles.length}</p></CardContent></Card><Card className="border-zinc-800 bg-[#101213]"><CardContent className="p-4"><p className="text-xs text-zinc-500">Servicios</p><p className="mt-1 text-2xl font-bold">12</p></CardContent></Card><Card className="border-zinc-800 bg-[#101213]"><CardContent className="p-4"><p className="text-xs text-zinc-500">Último servicio</p><p className="mt-1 text-sm font-semibold">04 OCT 2026</p></CardContent></Card><Card className="border-zinc-800 bg-[#101213]"><CardContent className="p-4"><p className="text-xs text-zinc-500">RODEX IDs</p><p className="mt-1 text-2xl font-bold">{client.motorcycles.length}</p></CardContent></Card></div><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Información de contacto</CardTitle></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><label className="text-xs text-zinc-400">Teléfono<Input value={client.phone} onChange={(event) => updateClient('phone', event.target.value)} className="mt-2 border-zinc-800 bg-zinc-900" /></label><label className="text-xs text-zinc-400">Correo electrónico<Input value={client.email} onChange={(event) => updateClient('email', event.target.value)} className="mt-2 border-zinc-800 bg-zinc-900" /></label><p className="text-sm text-zinc-500">Documento: No registrado</p><p className="text-sm text-zinc-500">Dirección: No registrada</p></CardContent></Card><div className="flex flex-col gap-3"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-lg font-bold">Motocicletas</h3><p className="text-sm text-zinc-500">{client.motorcycles.length} motocicleta{client.motorcycles.length === 1 ? '' : 's'} asociada{client.motorcycles.length === 1 ? '' : 's'}</p></div><Button type="button" onClick={() => setAddMoto(true)} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">+ Añadir moto</Button></div>{client.motorcycles.map((moto) => <Card key={moto.rodex} className="border-zinc-800 bg-[#101213]"><CardContent className="flex flex-col gap-4 p-4 sm:flex-row sm:items-center"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{moto.brand} {moto.model}</p><Badge variant="outline" className="border-emerald-500/30 text-emerald-400">{moto.state}</Badge></div><p className="mt-1 text-sm text-zinc-400">{moto.plate} · {moto.year} · {moto.color} · {moto.km} km</p><p className="mt-1 font-mono text-xs text-[#ed1c24]">{moto.rodex}</p><p className="mt-1 text-xs text-zinc-600">Último mantenimiento: 04 OCT 2026 · Próximo: 500 km</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" className="border-zinc-700">Ver ficha</Button><Button size="sm" variant="outline" className="border-zinc-700">Nuevo servicio</Button><Button size="sm" variant="outline" className="border-zinc-700">Ver QR</Button></div></CardContent></Card>)}</div>{addMoto && <div role="dialog" aria-modal="true" className="fixed inset-0 z-50 flex items-end justify-center bg-black/75 p-3 sm:items-center"><Card className="w-full max-w-lg border-zinc-800 bg-[#101213]"><CardHeader><CardTitle>Añadir motocicleta</CardTitle><p className="text-sm text-zinc-500">Asocia una motocicleta existente o registra una nueva.</p></CardHeader><CardContent className="grid gap-3"><Button type="button" variant="outline" onClick={() => { setAddMoto(false); setNewMoto(true) }} className="h-auto justify-start border-zinc-700 p-4 text-left"><span><b>Registrar nueva motocicleta</b><br /><small className="text-zinc-500">Crea una nueva ficha y genera un RODEX ID.</small></span></Button><Button type="button" variant="outline" className="h-auto justify-start border-zinc-700 p-4 text-left"><span><b>Vincular motocicleta existente</b><br /><small className="text-zinc-500">Busca una motocicleta previamente registrada.</small></span></Button><Button type="button" variant="ghost" onClick={() => setAddMoto(false)}>Cancelar</Button></CardContent></Card></div>}{newMoto && <div role="dialog" aria-modal="true" className="fixed inset-0 z-50 flex items-end justify-center overflow-y-auto bg-black/75 p-3 sm:items-center"><Card className="my-4 w-full max-w-2xl border-zinc-800 bg-[#101213]"><CardHeader><CardTitle>Registrar nueva motocicleta</CardTitle><p className="text-sm text-zinc-500">Paso {step} de 4 · Generaremos el RODEX ID automáticamente.</p></CardHeader><CardContent className="grid gap-4">{step === 1 && <div className="grid gap-4 sm:grid-cols-2">{[['plate','Placa *'],['brand','Marca *'],['model','Modelo *'],['year','Año'],['engine','Cilindraje'],['color','Color'],['vin','VIN / chasis'],['motor','Número de motor']].map(([key,label]) => <label key={key} className="text-xs text-zinc-400">{label}<Input className="mt-2 border-zinc-800 bg-zinc-900" placeholder={label.replace(' *','')} /></label>)}</div>}{step === 2 && <div className="grid gap-4 sm:grid-cols-2"><label className="text-xs text-zinc-400">Kilometraje actual *<Input type="number" className="mt-2 border-zinc-800 bg-zinc-900" /></label><label className="text-xs text-zinc-400">Nivel de combustible<Input className="mt-2 border-zinc-800 bg-zinc-900" /></label><label className="text-xs text-zinc-400 sm:col-span-2">Observaciones<textarea className="mt-2 min-h-24 w-full rounded-lg border border-zinc-800 bg-zinc-900 p-3 text-sm" /></label><label className="text-xs text-zinc-400 sm:col-span-2">Fotos iniciales<input type="file" accept="image/*" multiple className="mt-2 block w-full text-xs" /></label><label className="text-xs text-zinc-400 sm:col-span-2">Video opcional<input type="file" accept="video/*" className="mt-2 block w-full text-xs" /></label></div>}{step === 3 && <div className="rounded-xl border border-[#ed1c24]/30 bg-[#ed1c24]/5 p-6 text-center"><p className="text-xs uppercase tracking-widest text-zinc-500">RODEX ID</p><p className="mt-2 font-mono text-3xl font-bold text-[#ed1c24]">RX-004825</p><p className="mt-2 text-sm text-zinc-400">Este identificador único pertenecerá a la motocicleta y conservará su historial técnico.</p></div>}{step === 4 && <div className="grid gap-3 rounded-xl border border-zinc-800 p-4 text-sm"><p><span className="text-zinc-500">Cliente:</span> {client.name}</p><p><span className="text-zinc-500">Motocicleta:</span> Nueva motocicleta</p><p><span className="text-zinc-500">RODEX ID:</span> RX-004825</p><p><span className="text-zinc-500">Estado:</span> Activa</p></div>}<div className="flex justify-between gap-2"><Button type="button" variant="ghost" onClick={() => { setNewMoto(false); setStep(1) }}>Cancelar</Button>{step > 1 && <Button type="button" variant="outline" onClick={() => setStep((value) => value - 1)} className="border-zinc-700">Atrás</Button>}{step < 4 ? <Button type="button" onClick={() => setStep((value) => value + 1)} className="bg-[#ed1c24] text-white">Continuar</Button> : <Button type="button" onClick={() => { setNewMoto(false); setStep(1); setCreated(true) }} className="bg-[#ed1c24] text-white">Crear y generar RODEX ID</Button>}</div></CardContent></Card></div>}</div>; return <div className="flex flex-col gap-5"><div className="flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 size-4 text-zinc-500" /><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar cliente por nombre, teléfono, correo o placa" className="border-zinc-800 bg-[#101213] pl-9" /></div><select value={filter} onChange={(event) => setFilter(event.target.value)} className="h-10 rounded-md border border-zinc-800 bg-[#101213] px-3 text-sm text-zinc-300"><option>Todos</option><option>Con motos</option><option>Sin motos</option><option>Activo</option><option>Inactivo</option></select></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{matches.map((item) => <Card key={item.name} className="border-zinc-800/80 bg-[#101213]"><CardContent className="flex flex-col gap-4 p-5"><div className="flex items-start gap-3"><Avatar className="size-11"><AvatarFallback className="bg-[#ed1c24]/15 text-[#ed1c24]">{item.name.split(' ').map((part) => part[0]).join('').slice(0,2)}</AvatarFallback></Avatar><div className="min-w-0 flex-1"><h3 className="font-semibold">{item.name}</h3><p className="mt-1 text-xs text-zinc-500">{item.email}</p><p className="mt-1 text-xs text-zinc-500">{item.phone}</p></div><Badge variant="outline" className="border-emerald-500/30 text-emerald-400">{item.status}</Badge></div><div className="flex items-center justify-between border-t border-zinc-800 pt-3"><span className="text-xs text-zinc-500">{item.motorcycles.length} motocicletas · Registro {item.registered}</span><Button type="button" size="sm" onClick={() => setSelected(item.name)} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">Ver cliente</Button></div></CardContent></Card>)}</div>{matches.length === 0 && <Card className="border-zinc-800 bg-[#101213]"><CardContent className="p-8 text-center text-sm text-zinc-500">No encontramos clientes con esos criterios.</CardContent></Card>}</div> }

function InventoryPro() { const [query, setQuery] = useState(''); const [filter, setFilter] = useState('Todos'); const [selected, setSelected] = useState<string | null>(null); const products = [{ name: 'Castrol Power1 20W-50 1L', sku: 'ACE-2050', category: 'Aceites', brand: 'Castrol', stock: 24, min: 10, cost: 28500, sale: 42000, location: 'A-01', movement: 'Hoy, 14:42' }, { name: 'Filtro Hunk 160', sku: 'FIL-H160', category: 'Filtros', brand: 'Hero', stock: 7, min: 5, cost: 12000, sale: 20000, location: 'B-03', movement: 'Ayer, 16:20' }, { name: 'Lubricante de cadena', sku: 'LUB-001', category: 'Lubricantes', brand: 'Motul', stock: 3, min: 8, cost: 15000, sale: 25000, location: 'A-04', movement: '02 OCT 2026' }, { name: 'Pastillas de freno delanteras', sku: 'FRE-220', category: 'Frenos', brand: 'Brembo', stock: 0, min: 4, cost: 65000, sale: 95000, location: 'C-02', movement: '28 SEP 2026' }]; const matches = products.filter((product) => `${product.name} ${product.sku} ${product.brand}`.toLowerCase().includes(query.toLowerCase()) && (filter === 'Todos' || (filter === 'Stock bajo' && product.stock > 0 && product.stock < product.min) || (filter === 'Agotados' && product.stock === 0) || product.category === filter)); const totalUnits = products.reduce((sum, product) => sum + product.stock, 0); const costValue = products.reduce((sum, product) => sum + product.stock * product.cost, 0); const saleValue = products.reduce((sum, product) => sum + product.stock * product.sale, 0); const lowStock = products.filter((product) => product.stock < product.min).length; const detail = products.find((product) => product.name === selected); if (detail) return <div className="flex flex-col gap-5"><Button type="button" variant="ghost" onClick={() => setSelected(null)} className="w-fit text-zinc-400">← Volver a inventario</Button><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><p className="font-mono text-xs text-[#ed1c24]">{detail.sku}</p><CardTitle className="mt-2">{detail.name}</CardTitle><p className="mt-1 text-sm text-zinc-500">{detail.brand} · {detail.category} · Ubicación {detail.location}</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" className="border-zinc-700">Registrar entrada</Button><Button size="sm" className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">Ajustar stock</Button></div></CardHeader><CardContent className="flex flex-col gap-5"><div className="grid grid-cols-2 gap-3 sm:grid-cols-5">{[['Stock',String(detail.stock)],['Mínimo',String(detail.min)],['Costo',`$${detail.cost.toLocaleString('es-CO')}`],['Venta',`$${detail.sale.toLocaleString('es-CO')}`],['Margen',`${Math.round((1-detail.cost/detail.sale)*100)}%`]].map(([label,value]) => <div key={label} className="rounded-xl border border-zinc-800 bg-zinc-900/50 p-3"><p className="text-[10px] uppercase text-zinc-500">{label}</p><p className="mt-1 font-bold">{value}</p></div>)}</div><div className="flex flex-wrap gap-2"><Button size="sm" variant="secondary">Resumen</Button><Button size="sm" variant="outline" className="border-zinc-700">Movimientos (12)</Button><Button size="sm" variant="outline" className="border-zinc-700">Historial de costos</Button><Button size="sm" variant="outline" className="border-zinc-700">Uso en servicios</Button><Button size="sm" variant="outline" className="border-zinc-700">Proveedores</Button></div><div className="rounded-xl border border-zinc-800 p-4"><p className="font-semibold">Últimos movimientos</p><div className="mt-3 grid gap-2 text-xs text-zinc-400"><p className="flex justify-between border-b border-zinc-800 pb-2"><span>Uso en OT-000245 · Hunk 160 2V</span><span className="text-red-400">-1</span></p><p className="flex justify-between border-b border-zinc-800 pb-2"><span>Compra #0032 · Carlos Ramírez</span><span className="text-emerald-400">+24</span></p><p className="flex justify-between"><span>Conteo físico · Administrador</span><span>-2</span></p></div></div></CardContent></Card></div>; return <div className="flex flex-col gap-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-[#ed1c24]">Control de inventario</p><h2 className="mt-2 text-2xl font-bold">Inventario</h2><p className="mt-1 text-sm text-zinc-500">Existencias, rentabilidad y trazabilidad del taller.</p></div><div className="flex gap-2"><Button variant="outline" className="border-zinc-700">Reportes</Button><Button className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">+ Agregar producto</Button></div></div><div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{[['Unidades',String(totalUnits),'Inventario físico'],['Costo',`$${costValue.toLocaleString('es-CO')}`,'Costo adquisición'],['Venta potencial',`$${saleValue.toLocaleString('es-CO')}`,'Valor de venta'],['Ganancia',`$${(saleValue-costValue).toLocaleString('es-CO')}`,'Margen potencial'],['Stock bajo',String(lowStock),'Requieren atención'],['Agotados','1','Sin existencias'],['Por llegar','2','Compras en tránsito'],['Consumo mes','18','Unidades usadas']].map(([label,value,caption]) => <button type="button" key={label} onClick={() => setFilter(label === 'Stock bajo' ? 'Stock bajo' : label === 'Agotados' ? 'Agotados' : 'Todos')} className="rounded-xl border border-zinc-800 bg-[#101213] p-4 text-left transition hover:border-[#ed1c24]/50"><p className="text-[10px] uppercase tracking-wider text-zinc-500">{label}</p><p className="mt-2 text-xl font-bold">{value}</p><p className="mt-1 text-[10px] text-zinc-600">{caption}</p></button>)}</div><div className="flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 size-4 text-zinc-500" /><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por nombre, SKU, marca o referencia..." className="h-10 border-zinc-800 bg-[#101213] pl-9" /></div><select value={filter} onChange={(event) => setFilter(event.target.value)} className="h-10 rounded-md border border-zinc-800 bg-[#101213] px-3 text-sm text-zinc-300"><option>Todos</option><option>Stock bajo</option><option>Agotados</option><option>Aceites</option><option>Filtros</option><option>Lubricantes</option><option>Frenos</option></select></div><div className="grid gap-3 lg:grid-cols-2">{matches.map((product) => { const margin = Math.round((1-product.cost/product.sale)*100); const status = product.stock === 0 ? 'Agotado' : product.stock < product.min ? 'Stock bajo' : 'Disponible'; return <button type="button" key={product.sku} onClick={() => setSelected(product.name)} className="flex flex-col gap-3 rounded-xl border border-zinc-800 bg-[#101213] p-4 text-left transition hover:border-[#ed1c24]/50 sm:flex-row sm:items-center"><div className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-[#ed1c24]/10 font-mono text-xs text-[#ed1c24]">{product.sku.slice(0,3)}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{product.name}</p><Badge variant="outline" className={status === 'Agotado' ? 'border-red-500/40 text-red-400' : status === 'Stock bajo' ? 'border-amber-500/40 text-amber-400' : 'border-emerald-500/40 text-emerald-400'}>{status}</Badge></div><p className="mt-1 text-xs text-zinc-500">{product.sku} · {product.brand} · {product.category} · {product.location}</p></div><div className="grid grid-cols-3 gap-4 text-right text-xs"><div><p className="text-zinc-600">Stock</p><p className="mt-1 font-semibold">{product.stock} / {product.min}</p></div><div><p className="text-zinc-600">Costo</p><p className="mt-1">${product.cost.toLocaleString('es-CO')}</p></div><div><p className="text-zinc-600">Margen</p><p className="mt-1 text-emerald-400">{margin}%</p></div></div></button>})}</div>{matches.length === 0 && <Card className="border-zinc-800 bg-[#101213]"><CardContent className="p-8 text-center text-sm text-zinc-500">No hay productos que coincidan con los filtros.</CardContent></Card>}<div className="grid gap-5 lg:grid-cols-2"><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Alertas de inventario</CardTitle><p className="text-sm text-zinc-500">Atención prioritaria del taller.</p></CardHeader><CardContent className="flex flex-col gap-2"><p className="rounded-lg border border-red-500/20 bg-red-500/5 p-3 text-xs text-red-300">Agotado: Pastillas de freno delanteras · <Button variant="link" className="h-auto p-0 text-red-300">Crear pedido</Button></p><p className="rounded-lg border border-amber-500/20 bg-amber-500/5 p-3 text-xs text-amber-300">Lubricante de cadena está por debajo del stock mínimo.</p><p className="rounded-lg border border-blue-500/20 bg-blue-500/5 p-3 text-xs text-blue-300">Batería YTX7A-BS · 10 unidades · llega 12 OCT 2026.</p></CardContent></Card><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Últimos productos utilizados</CardTitle><p className="text-sm text-zinc-500">Trazabilidad vinculada a órdenes y motocicletas.</p></CardHeader><CardContent className="flex flex-col gap-2">{[['Castrol Power1 20W-50','Carlos Rodríguez','Hunk 160 2V','RX-004821','OT-000184','1 unidad'],['Filtro Hunk 160','Carlos Ramírez','NKD 125','RX-004822','OT-000185','1 unidad']].map(([product,tech,moto,rodex,order,qty]) => <div key={order} className="rounded-lg border border-zinc-800 p-3 text-xs"><p className="font-semibold">{product}</p><p className="mt-1 text-zinc-500">{tech} · {moto} · {rodex}</p><p className="mt-1 text-zinc-600">{order} · Hoy, 14:42 · {qty}</p></div>)}</CardContent></Card></div></div> }

function Inventory() { const [items, setItems] = useState([{ name: 'Kit de arrastre', qty: 12, price: 185000, status: 'Stock bajo' }, { name: 'Aceite 10W40', qty: 48, price: 28000, status: 'Disponible' }, { name: 'Pastillas de freno', qty: 3, price: 65000, status: 'Stock bajo' }, { name: 'Filtros de aceite', qty: 72, price: 20000, status: 'Disponible' }]); const [showAdd, setShowAdd] = useState(false); const [draft, setDraft] = useState({ name: '', qty: '1', price: '' }); const [incoming, setIncoming] = useState([{ name: 'Batería YTX7A-BS', qty: 10, date: '12 OCT 2026' }, { name: 'Neumático trasero 130/70', qty: 6, date: '18 OCT 2026' }]); const total = items.reduce((sum, item) => sum + item.qty * item.price, 0); const addItem = () => { if (!draft.name || !draft.price) return; setItems((current) => [...current, { name: draft.name, qty: Number(draft.qty) || 1, price: Number(draft.price), status: 'Disponible' }]); setDraft({ name: '', qty: '1', price: '' }); setShowAdd(false) }; return <div className="flex flex-col gap-6"><div className="grid gap-4 sm:grid-cols-3"><Card className="border-zinc-800/80 bg-[#101213]"><CardContent className="p-5"><p className="text-xs text-zinc-500">Valor aproximado total</p><p className="mt-2 text-2xl font-bold">${total.toLocaleString('es-CO')}</p><p className="mt-1 text-xs text-zinc-600">Costo de adquisición estimado</p></CardContent></Card><Card className="border-zinc-800/80 bg-[#101213]"><CardContent className="p-5"><p className="text-xs text-zinc-500">Unidades en inventario</p><p className="mt-2 text-2xl font-bold">{items.reduce((sum, item) => sum + item.qty, 0)}</p></CardContent></Card><Card className="border-zinc-800/80 bg-[#101213]"><CardContent className="p-5"><p className="text-xs text-zinc-500">Productos por llegar</p><p className="mt-2 text-2xl font-bold">{incoming.length}</p></CardContent></Card></div>{showAdd && <Card className="border-[#ed1c24]/40 bg-[#101213]"><CardHeader><CardTitle>Ingreso de mercancía</CardTitle></CardHeader><CardContent className="grid gap-4 sm:grid-cols-3"><label className="text-xs text-zinc-400">Producto<Input value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} className="mt-2 border-zinc-800 bg-zinc-900" placeholder="Nombre del producto" /></label><label className="text-xs text-zinc-400">Cantidad<Input type="number" value={draft.qty} onChange={(event) => setDraft({ ...draft, qty: event.target.value })} className="mt-2 border-zinc-800 bg-zinc-900" /></label><label className="text-xs text-zinc-400">Valor unitario<Input type="number" value={draft.price} onChange={(event) => setDraft({ ...draft, price: event.target.value })} className="mt-2 border-zinc-800 bg-zinc-900" placeholder="28000" /></label><div className="flex gap-2 sm:col-span-3"><Button type="button" onClick={addItem} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]">Registrar ingreso</Button><Button type="button" variant="outline" onClick={() => setShowAdd(false)} className="border-zinc-700">Cancelar</Button></div></CardContent></Card>}<div className="flex justify-end"><Button type="button" onClick={() => setShowAdd(true)} className="bg-[#ed1c24] text-white hover:bg-[#c9151c]"><Plus className="mr-2 size-4" /> Ingreso de mercancía</Button></div><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Existencias y valoración</CardTitle></CardHeader><CardContent className="flex flex-col gap-3">{items.map((item, index) => <div key={`${item.name}-${index}`} className="grid gap-3 rounded-lg border border-zinc-800 p-4 sm:grid-cols-[1fr_110px_140px_auto] sm:items-center"><Boxes className="hidden size-4 text-[#ed1c24] sm:block" /><div><p className="text-sm font-medium">{item.name}</p><p className="mt-1 text-xs text-zinc-500">{item.qty} unidades · ${item.price.toLocaleString('es-CO')} c/u</p></div><Input type="number" value={item.qty} onChange={(event) => setItems((current) => current.map((entry, entryIndex) => entryIndex === index ? { ...entry, qty: Number(event.target.value) } : entry))} className="border-zinc-800 bg-zinc-900" /><Input type="number" value={item.price} onChange={(event) => setItems((current) => current.map((entry, entryIndex) => entryIndex === index ? { ...entry, price: Number(event.target.value) } : entry))} className="border-zinc-800 bg-zinc-900" /><Badge variant="outline" className={item.status === 'Stock bajo' ? 'border-amber-500/30 text-amber-400' : 'border-emerald-500/30 text-emerald-400'}>{item.status}</Badge></div>)}</CardContent></Card><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Productos próximos a llegar</CardTitle></CardHeader><CardContent className="flex flex-col gap-3">{incoming.map((item, index) => <div key={item.name} className="flex flex-wrap items-center gap-3 rounded-lg border border-zinc-800 p-4"><Boxes className="size-4 text-amber-400" /><span className="flex-1 text-sm">{item.name}</span><span className="text-xs text-zinc-500">{item.qty} unidades · {item.date}</span><Button type="button" variant="ghost" size="sm" onClick={() => setIncoming((current) => current.filter((_, itemIndex) => itemIndex !== index))}>Recibido</Button></div>)}</CardContent></Card></div> }
function InventoryInsights() { return <div className="grid gap-5 lg:grid-cols-2"><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Últimos productos utilizados</CardTitle><p className="text-sm text-zinc-500">Trazabilidad de cada salida del inventario.</p></CardHeader><CardContent className="flex flex-col gap-3">{[['Aceite 10W40','Carlos Ramírez','Hunk 160 2V · ABC123','Hoy, 10:42'],['Kit de arrastre','Andrés López','Pulsar NS 200 · JFT492','Ayer, 16:20'],['Filtro de aceite','Carlos Ramírez','NKD 125 · KLM768','02 OCT 2026']].map(([product,person,moto,date]) => <div key={`${product}-${date}`} className="flex flex-wrap items-center gap-3 rounded-xl border border-zinc-800 p-3"><div className="flex size-9 items-center justify-center rounded-lg bg-[#ed1c24]/10 text-[#ed1c24]"><Boxes className="size-4" /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{product}</p><p className="text-xs text-zinc-500">{moto}</p></div><div className="text-right text-[11px] text-zinc-500"><p>{person}</p><p>{date}</p></div></div>)}</CardContent></Card><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Estado de abastecimiento</CardTitle><p className="text-sm text-zinc-500">Productos en tránsito y fechas estimadas.</p></CardHeader><CardContent className="flex flex-col gap-3">{[['Batería YTX7A-BS','10 unidades','12 OCT 2026','En tránsito'],['Neumático trasero 130/70','6 unidades','18 OCT 2026','Confirmado']].map(([product,qty,date,status]) => <div key={product} className="flex flex-wrap items-center gap-3 rounded-xl border border-zinc-800 p-3"><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{product}</p><p className="text-xs text-zinc-500">{qty} · llegada {date}</p></div><Badge variant="outline" className="border-amber-500/30 text-amber-400">{status}</Badge></div>)}</CardContent></Card></div> }

function Loyalty() { return <div className="grid gap-6 md:grid-cols-3">{[['RODEX ORO','18 clientes','1.240 puntos'],['RODEX PLATA','46 clientes','860 puntos'],['RODEX BRONCE','64 clientes','420 puntos']].map(([tier,customers,points], i) => <Card key={tier} className="border-zinc-800/80 bg-[#101213]"><CardContent className="p-6"><Sparkles className={`size-7 ${i === 0 ? 'text-amber-400' : 'text-zinc-400'}`} /><h2 className="mt-5 text-xl font-bold">{tier}</h2><p className="mt-2 text-sm text-zinc-400">{customers}</p><p className="mt-6 text-2xl font-bold">{points}</p><p className="mt-1 text-xs text-zinc-600">acumulados este mes</p></CardContent></Card>)}</div> }
function Reports() { return <div className="grid gap-6 md:grid-cols-2"><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Rendimiento mensual</CardTitle></CardHeader><CardContent><div className="flex h-44 items-end gap-3">{[48,68,55,82,70,93,78,88,64,91,76,98].map((height, index) => <div key={index} className="flex flex-1 flex-col justify-end gap-2"><div className="rounded-t bg-[#ed1c24]" style={{ height: `${height}%` }} /><span className="text-center text-[9px] text-zinc-600">{index + 1}</span></div>)}</div></CardContent></Card><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Indicadores clave</CardTitle></CardHeader><CardContent className="flex flex-col gap-4">{[['Servicios completados','184','+14.2%'],['Ticket promedio','$184.500','+8.7%'],['Satisfacción','96%','+2.1%']].map(([label,value,trend]) => <div key={label} className="flex items-center justify-between border-b border-zinc-800 pb-4"><div><p className="text-xs text-zinc-500">{label}</p><p className="mt-1 text-xl font-bold">{value}</p></div><span className="text-xs text-emerald-400">{trend}</span></div>)}</CardContent></Card></div> }
function SettingsView() { return <div className="grid gap-6 xl:grid-cols-[0.7fr_1.3fr]"><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Configuración</CardTitle></CardHeader><CardContent className="flex flex-col gap-2">{['Perfil del taller','Usuarios y permisos','Notificaciones','Facturación','Integraciones'].map((item, index) => <button type="button" key={item} className={`rounded-lg px-4 py-3 text-left text-sm ${index === 0 ? 'bg-[#ed1c24]/10 text-white' : 'text-zinc-500 hover:bg-zinc-900 hover:text-white'}`}>{item}</button>)}</CardContent></Card><Card className="border-zinc-800/80 bg-[#101213]"><CardHeader><CardTitle>Perfil del taller</CardTitle><p className="text-sm text-zinc-500">Administra la información visible para tus clientes.</p></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><label className="text-xs text-zinc-400">Nombre del taller<Input className="mt-2 border-zinc-800 bg-zinc-900" defaultValue="RODEX Motorcycles" /></label><label className="text-xs text-zinc-400">Correo de contacto<Input className="mt-2 border-zinc-800 bg-zinc-900" defaultValue="hola@rodex.co" /></label><label className="text-xs text-zinc-400">Ciudad<Input className="mt-2 border-zinc-800 bg-zinc-900" defaultValue="Cali, Colombia" /></label><label className="text-xs text-zinc-400">Teléfono<Input className="mt-2 border-zinc-800 bg-zinc-900" defaultValue="+57 300 123 4567" /></label><Button className="bg-[#ed1c24] text-white hover:bg-[#c9151c] sm:col-span-2">Guardar cambios</Button></CardContent></Card></div> }
